 ]},
 {"clause_id": "c029", "issues": []},
 {"clause_id": "c030", "issues": [
   {"issue": "This paragraph's pollution exclusion, with its \"sudden and accidental\" exception, is the very exclusion the Total Pollution Exclusion (c099) says it \"replaces,\" and the two describe the excluded substances differently. Which text governs a pollution claim requires reading them together.", "type": 2, "prob": 0.28}
 ]},
 {"clause_id": "c031", "issues": [
